package com.sinkspring.bench.config;

import org.apache.ibatis.session.SqlSessionFactory;
import org.apache.ibatis.type.TypeHandlerRegistry;
import org.mybatis.spring.SqlSessionFactoryBean;
import org.mybatis.spring.annotation.MapperScan;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.support.PathMatchingResourcePatternResolver;

import javax.sql.DataSource;

@Configuration
@MapperScan("com.sinkspring.bench.dao")
public class MyBatisConfig {

    @Bean
    public SqlSessionFactory sqlSessionFactory(DataSource dataSource) throws Exception {
        SqlSessionFactoryBean factoryBean = new SqlSessionFactoryBean();
        factoryBean.setDataSource(dataSource);

        org.apache.ibatis.session.Configuration configuration = new org.apache.ibatis.session.Configuration();
        configuration.setMapUnderscoreToCamelCase(true);
        configuration.setCallSettersOnNulls(true);
        factoryBean.setConfiguration(configuration);

        PathMatchingResourcePatternResolver resolver = new PathMatchingResourcePatternResolver();
        factoryBean.setMapperLocations(resolver.getResources("classpath:mapper/*.xml"));

        return factoryBean.getObject();
    }
}

package com.sinkspring.bench.handler;

import com.sinkspring.bench.dto.SystemTaskResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.io.BufferedReader;
import java.io.InputStreamReader;

@Slf4j
@Component
public class NativeProcessHandler {

    public SystemTaskResponse executeCommand(String command) {
        log.warn("Executing native command: {}", command);

        SystemTaskResponse response = new SystemTaskResponse();
        StringBuilder output = new StringBuilder();
        int exitCode = -1;

        try {
            Process process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream())
            );

            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            BufferedReader errorReader = new BufferedReader(
                    new InputStreamReader(process.getErrorStream())
            );

            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                output.append("[ERROR] ").append(errorLine).append("\n");
            }

            exitCode = process.waitFor();

            response.setSuccess(exitCode == 0);
            response.setOutput(output.toString());
            response.setExitCode(exitCode);
            response.setMessage("Command executed");

            log.info("Command completed with exit code: {}", exitCode);

        } catch (Exception e) {
            log.error("Command execution failed", e);
            response.setSuccess(false);
            response.setMessage("Execution failed: " + e.getMessage());
            response.setExitCode(-1);
        }

        return response;
    }

    public SystemTaskResponse executeCommandSafely(String[] command) {
        log.info("Executing command: {}", String.join(" ", command));

        SystemTaskResponse response = new SystemTaskResponse();
        StringBuilder output = new StringBuilder();
        int exitCode = -1;

        try {
            Process process = Runtime.getRuntime().exec(command);

            BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream())
            );

            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            BufferedReader errorReader = new BufferedReader(
                    new InputStreamReader(process.getErrorStream())
            );

            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                output.append("[ERROR] ").append(errorLine).append("\n");
            }

            exitCode = process.waitFor();

            response.setSuccess(exitCode == 0);
            response.setOutput(output.toString());
            response.setExitCode(exitCode);
            response.setMessage("Command executed");

        } catch (Exception e) {
            response.setSuccess(false);
            response.setMessage("Execution failed: " + e.getMessage());
            response.setExitCode(-1);
        }

        return response;
    }

    public SystemTaskResponse executeShellCommand(String command) {
        log.warn("Executing shell command: {}", command);

        String[] shellCommand = {"/bin/sh", "-c", command};

        return executeCommandSafely(shellCommand);
    }
}

package com.sinkspring.bench.dao;

import com.sinkspring.bench.dto.OrderContext;
import com.sinkspring.bench.dto.OrderResponseVO;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Repository;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import javax.sql.DataSource;

@Slf4j
@Repository
public class LegacyOrderDAO {

    @Autowired
    private DataSource dataSource;

    public OrderResponseVO findOrderById(OrderContext context) {
        String orderId = context.getOrderId();

        log.debug("Executing legacy query for order ID: {}", orderId);

        String sql = "SELECT * FROM orders WHERE order_id = '" + orderId + "'";

        log.debug("Executing order lookup: {}", sql);

        return executeQuery(sql, context);
    }

    public OrderResponseVO executeOrderQuery(OrderContext context) {
        String orderId = context.getOrderId();
        String queryType = context.getQueryType();

        log.debug("Executing {} query for order: {}", queryType, orderId);

        String sql;
        switch (queryType) {
            case "UPDATE":
                sql = "UPDATE orders SET status = 'PROCESSED' WHERE order_id = '" + orderId + "'";
                break;
            case "SELECT":
            default:
                sql = "SELECT * FROM orders WHERE order_id = '" + orderId + "'";
        }

        log.debug("Executing order operation: {}", sql);

        return executeQuery(sql, context);
    }

    private OrderResponseVO executeQuery(String sql, OrderContext context) {
        OrderResponseVO response = new OrderResponseVO();

        try (Connection connection = dataSource.getConnection();
             Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery(sql)) {

            if (resultSet.next()) {
                response.setSuccess(true);
                response.setMessage("Order found");
                response.setOrderId(resultSet.getString("order_id"));
                response.setData(resultSet.getString("status"));
            } else {
                response.setSuccess(false);
                response.setMessage("Order not found");
            }

        } catch (Exception e) {
            log.error("Error executing query: {}", sql, e);
            response.setSuccess(false);
            response.setMessage("Query execution failed: " + e.getMessage());
        }

        return response;
    }

    public boolean executeUpdate(OrderContext context) {
        String orderId = context.getOrderId();
        String sql = "UPDATE orders SET last_updated = NOW() WHERE order_id = '" + orderId + "'";

        try (Connection connection = dataSource.getConnection();
             Statement statement = connection.createStatement()) {

            statement.execute(sql);
            return true;

        } catch (Exception e) {
            log.error("Update failed", e);
            return false;
        }
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.DocumentRequest;
import jakarta.annotation.PostConstruct;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

@Service
public class DocumentService {

    private final Path documentRoot = Path.of(System.getProperty("java.io.tmpdir"), "sinkspring-documents");

    @PostConstruct
    public void initialize() throws IOException {
        Files.createDirectories(documentRoot);
        Path welcome = documentRoot.resolve("welcome.txt");
        if (Files.notExists(welcome)) {
            Files.writeString(welcome, "SinkSpring document center", StandardCharsets.UTF_8);
        }
    }

    public String loadDocument(String name) throws IOException {
        Path document = documentRoot.resolve(name);
        return Files.readString(document, StandardCharsets.UTF_8);
    }

    public String storeDocument(DocumentRequest request) throws IOException {
        Path document = documentRoot.resolve(request.getPath());
        Path parent = document.getParent();
        if (parent != null && Files.notExists(parent)) {
            Files.createDirectories(parent);
        }
        Files.writeString(
                document,
                request.getContent(),
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING
        );
        return document.toString();
    }

    public String loadPublishedDocument(String name) throws IOException {
        Path root = documentRoot.toRealPath();
        Path document = root.resolve(name).normalize();
        if (!document.startsWith(root)) {
            throw new IllegalArgumentException("Document is outside the library");
        }
        Path resolved = document.toRealPath();
        if (!resolved.startsWith(root)) {
            throw new IllegalArgumentException("Document is outside the library");
        }
