@Slf4j
@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @Autowired
    private OrderService orderService;

    @GetMapping("/{orderId}")
    public OrderResponseVO getOrderById(@PathVariable String orderId) {
        log.info("Received request for order ID: {}", orderId);

        OrderRequestDTO requestDTO = new OrderRequestDTO();
        requestDTO.setOrderId(orderId);

        return orderService.getOrderDetails(requestDTO);
    }

    @PostMapping("/process")
    public OrderResponseVO processOrder(@RequestBody OrderRequestDTO requestDTO) {
        log.info("Processing order with ID: {}", requestDTO.getOrderId());

        OrderContext context = new OrderContext();
        context.setOrderId(requestDTO.getOrderId());
        context.setCustomerId(requestDTO.getCustomerId());
        context.setAction(requestDTO.getAction());

        return orderService.processOrderAction(context);
    }

    @GetMapping("/legacy/view")
    public OrderResponseVO legacyViewOrder(@RequestParam String orderId) {
        log.info("Legacy view order request for ID: {}", orderId);

        OrderRequestDTO requestDTO = new OrderRequestDTO();
        requestDTO.setOrderId(orderId);
        requestDTO.setAction("VIEW");

        return orderService.handleLegacyRequest(requestDTO);
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dao.LegacyOrderDAO;
import com.sinkspring.bench.dto.OrderContext;
import com.sinkspring.bench.dto.OrderRequestDTO;
import com.sinkspring.bench.dto.OrderResponseVO;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Slf4j
@Service
public class OrderService {

    @Autowired
    private LegacyOrderDAO legacyOrderDAO;

    @Autowired
    private OrderContextFactory orderContextFactory;

    public OrderResponseVO getOrderDetails(OrderRequestDTO requestDTO) {
        log.info("Building order context for order ID: {}", requestDTO.getOrderId());

        OrderContext context = orderContextFactory.buildContext(requestDTO);

        return legacyOrderDAO.findOrderById(context);
    }

    public OrderResponseVO processOrderAction(OrderContext context) {
        log.info("Processing action {} for order: {}",
                 context.getAction(), context.getOrderId());

        enrichOrderContext(context);

        context.setRequiresLegacyHandling(true);

        return legacyOrderDAO.executeOrderQuery(context);
    }

    public OrderResponseVO handleLegacyRequest(OrderRequestDTO requestDTO) {
        log.debug("Handling legacy request for order: {}", requestDTO.getOrderId());

        OrderContext context = new OrderContext(
            requestDTO.getOrderId(),
            requestDTO.getCustomerId(),
            requestDTO.getAction(),
            requestDTO.getStatus()
        );

        context.setQueryType("LEGACY");
        context.addMetadata("source", "legacy_api");

        return legacyOrderDAO.findOrderById(context);
    }

    private void enrichOrderContext(OrderContext context) {
        context.addMetadata("processedAt", System.currentTimeMillis());
        context.addMetadata("processor", "OrderService");

        if ("VIEW".equals(context.getAction())) {
            context.setQueryType("SELECT");
        } else if ("UPDATE".equals(context.getAction())) {
            context.setQueryType("UPDATE");
        } else {
            context.setQueryType("SELECT");
        }
    }
}

package com.sinkspring.bench.service;

import com.sinkspring.bench.dto.OrderContext;
import com.sinkspring.bench.dto.OrderRequestDTO;
import org.springframework.stereotype.Component;

@Component
public class OrderContextFactory {

    public OrderContext buildContext(OrderRequestDTO requestDTO) {
        OrderContext context = new OrderContext();

        context.setOrderId(requestDTO.getOrderId());
        context.setCustomerId(requestDTO.getCustomerId());
        context.setAction(requestDTO.getAction());
        context.setStatus(requestDTO.getStatus());

        context.setQueryType("SELECT");

        context.addMetadata("source", "api");
        context.addMetadata("timestamp", System.currentTimeMillis());

        return context;
    }

    public void enrichContext(OrderContext context, String queryType) {
        context.setQueryType(queryType);
        context.setRequiresLegacyHandling(true);
    }
}

package com.sinkspring.bench.dto;

import lombok.Data;
import java.util.HashMap;
import java.util.Map;

@Data
public class OrderContext {
    private String orderId;
    private String customerId;
    private String action;
    private String status;

    private Map<String, Object> metadata;
    private String queryType;
    private boolean requiresLegacyHandling;

    public OrderContext() {
        this.metadata = new HashMap<>();
        this.requiresLegacyHandling = false;
    }

    public OrderContext(String orderId, String customerId, String action, String status) {
        this();
        this.orderId = orderId;
        this.customerId = customerId;
        this.action = action;
        this.status = status;
    }

    public void addMetadata(String key, Object value) {
        this.metadata.put(key, value);
    }

    public Object getMetadata(String key) {
        return this.metadata.get(key);
    }
}

